from math import gcd
from typing import Iterator

def collisions(limit: int) -> Iterator[dict[str, int | bool]]:
    """Generate cyclic–dihedral invariant collisions up to an order limit."""
    for n in range(3, limit // 2 + 1, 2):
        yield {"n": n, "order": 2 * n, "cyclic_exponent": 2 * n,
               "dihedral_exponent": n * 2 // gcd(n, 2),
               "cyclic_is_abelian": True, "dihedral_is_abelian": False,
               "cyclic_center_order": 2 * n, "dihedral_center_order": 1}

if __name__ == "__main__":
    for row in collisions(50):
        print(row)

from math import gcd

def totient(n: int) -> int:
    """Return the number of automorphisms of the cyclic group C_n."""
    if n < 1:
        raise ValueError("n must be positive")
    return sum(gcd(k, n) == 1 for k in range(1, n + 1))

if __name__ == "__main__":
    for n in range(1, 21):
        print(f"|Aut(C_{n})| = {totient(n)}")

from dataclasses import dataclass
from typing import Hashable, Iterable

@dataclass(frozen=True)
class Record:
    name: str
    fingerprint: tuple[Hashable, ...]
    label: bool

def impure_buckets(records: Iterable[Record]) -> dict[tuple[Hashable, ...], set[bool]]:
    buckets: dict[tuple[Hashable, ...], set[bool]] = {}
    for record in records:
        buckets.setdefault(record.fingerprint, set()).add(record.label)
    return {key: values for key, values in buckets.items() if len(values) > 1}

if __name__ == "__main__":
    data = [Record("C6", (6, 6), True), Record("D6", (6, 6), False)]
    print(impure_buckets(data))

